const items = function buildItemsTable(groups,utils,opts=true){const o=typeof opts==="boolean"?{showPrice:opts,showGroupSubtotal:opts}:opts;const showPrice=o.showPrice??true;const showGroupSubtotal=o.showGroupSubtotal??showPrice;const{fmtVND,fmtNum,groupLabel}=utils;const priceHdr=showPrice?`<th style="width:9%">\u0110\u01A1n gi\xE1<br/>(VN\u0110)</th><th style="width:10%">Th\xE0nh ti\u1EC1n<br/>(VN\u0110)</th>`:"";let rows="";groups.forEach((g,gi)=>{const label=groupLabel(gi);const specHtml=(g.spec??"").replace(/&/g,"&amp;").replace(/</g,"&lt;");rows+=`<tr><td class="c it-grp" style="font-weight:bold">${label}.</td>       <td colspan="${showPrice?7:5}" class="it-grp">${specHtml}</td></tr>`;if(showGroupSubtotal){const total_tt=g.items.reduce((s,i)=>s+(i.thanh_tien??0),0);const total_kl=g.items.reduce((s,i)=>s+(i.khoi_luong??0),0);const total_st=g.items.reduce((s,i)=>s+(i.so_tam??0),0);const prices=[...new Set(g.items.map(i=>i.don_gia).filter(Boolean))];const uniformPrice=prices.length===1?fmtVND(prices[0]):"";const priceSubCells=showPrice?`<td class="r it-sub">${uniformPrice}</td><td class="r it-sub">${fmtVND(total_tt)}</td>`:"";rows+=`<tr><td class="it-sub"></td><td class="it-sub" colspan="3">C\u1ED9ng nh\xF3m ${label} \u2013 ch\u01B0a VAT ${g.vat_rate}%</td>         <td class="r it-sub">${total_st}</td><td class="r it-sub">${fmtNum(total_kl)}</td>${priceSubCells}</tr>`}g.items.forEach((item,idx)=>{const priceCells=showPrice?`<td class="r">${item.don_gia!=null?fmtVND(item.don_gia):""}</td>            <td class="r">${item.thanh_tien?fmtVND(item.thanh_tien):""}</td>`:"";rows+=`<tr><td class="c">${idx+1}</td><td>${item.ten_sp??""}</td>         <td class="c">${item.don_vi??""}</td>         <td class="r">${item.chieu_rong!=null?fmtNum(item.chieu_rong):""}</td>         <td class="r">${item.chieu_dai!=null?fmtNum(item.chieu_dai,3):""}</td>         <td class="r">${item.so_tam!=null?item.so_tam:""}</td>         <td class="r">${item.khoi_luong!=null?fmtNum(item.khoi_luong):""}</td>         ${priceCells}</tr>`})});return`<table class="it"><thead><tr>     <th style="width:4%">TT</th>     <th style="width:${showPrice?"26%":"38%"}">T\xEAn s\u1EA3n ph\u1EA9m/Quy c\xE1ch</th>     <th style="width:5%">\u0110\u01A1n v\u1ECB</th>     <th style="width:7%">Chi\u1EC1u<br/>r\u1ED9ng</th>     <th style="width:8%">Chi\u1EC1u<br/>d\xE0i</th>     <th style="width:6%">S\u1ED1<br/>t\u1EA5m</th>     <th style="width:8%">Kh\u1ED1i<br/>l\u01B0\u1EE3ng</th>     ${priceHdr}</tr></thead><tbody>${rows}</tbody></table>`}(groups, utils, { showPrice: false, showGroupSubtotal: false });
const pxkNotes = utils.parseNoteLines ? utils.parseNoteLines(cfg.ghi_chu_lsx_pxk, []) : [];
const pxkNoteBlock = pxkNotes.length ? ('<div class="notes"><b>Ghi chú:</b>' + pxkNotes.map((n,i)=>'<div>'+(i+1)+'. '+n+'</div>').join('') + '</div>') : '';
const receive = '<div class="receive-line">Khách hàng nhận hàng lúc: …….... giờ …….. phút, ngày ….. tháng ….. năm ' + (parts[2]??new Date().getFullYear()) + '</div>';
